  function probe(u, cid) {
    var col = T[cid] || T[CASES[0]];
    if (!(u >= 0)) u = 0;
    if (u > 1) u = 1;
    var x = u * (N - 1), i = Math.floor(x), f = x - i;
    if (i >= N - 1) { i = N - 2; f = 1; }
    if (i < 0) { i = 0; f = 0; }
    var r = {}, k;
    for (k in col) r[k] = col[k][i] * (1 - f) + col[k][i + 1] * f;
    return r;
  }
  function probeAll(u) {
    var m = {}, i;
    for (i = 0; i < CASES.length; i++) m[CASES[i]] = probe(u, CASES[i]);
    return m;
  }
